"""#588: docs/operations/settings-reference.md lists every setting, generated by scripts/settings_reference.py from
where each is defined. A setting without a description, or a page that wasn't regenerated, fails here."""
from __future__ import annotations

import importlib.util
import sys
from pathlib import Path

from pydantic_settings import BaseSettings, SettingsConfigDict

ROOT = Path(__file__).resolve().parents[2]
_spec = importlib.util.spec_from_file_location("settings_reference", ROOT / "scripts" / "settings_reference.py")
sr = importlib.util.module_from_spec(_spec)
sys.modules["settings_reference"] = sr  # its dataclasses look themselves up there
_spec.loader.exec_module(sr)

RUN = "run python scripts/settings_reference.py"


def test_every_setting_has_a_description():
    _, missing = sr.build()
    assert not missing, "settings without a description:\n  " + "\n  ".join(missing)


def test_the_page_is_up_to_date():
    page, _ = sr.build()
    assert sr.OUT.read_text() == page, f"{sr.OUT.relative_to(ROOT)} is out of date: {RUN}"


def test_its_links_lead_somewhere():
    page, _ = sr.build()
    assert not sr.broken_links(page)


def test_secrets_have_no_value_to_show():
    """A secret's default in the code is empty, and the page says "generated" or "set when used" in its place."""
    from app.config import Settings
    from portal.config import PortalSettings

    page = sr.OUT.read_text()
    for model, prefix in ((Settings, ""), (PortalSettings, "PORTAL_")):
        for name, info in model.model_fields.items():
            env = (prefix + name).upper()
            if sr.is_secret(env) and isinstance(info.default, str):
                assert info.default == "", f"{env} has a default value in the code"
                assert f"| `{env}` | {sr.GENERATED} |" in page or f"| `{env}` | {sr.WHEN_USED} |" in page, env


def test_a_field_without_a_docstring_is_reported():
    class S(BaseSettings):
        model_config = SettingsConfigDict(use_attribute_docstrings=True)
        described: int = 1
        """What it does."""
        bare: int = 2

    missing: list[str] = []
    tables = sr.model_tables(S, "", [("All", "", ["described", "bare"])], {}, set(), missing)
    assert [r.name for r in tables[0].rows] == ["DESCRIBED", "BARE"]
    assert len(missing) == 1 and missing[0].startswith("BARE ")


def test_deploy_env_descriptions():
    """A comment over one line describes it; over several, each needs a "- KEY:" bullet of its own."""
    text = (
        "# The only one\n"
        "ALONE=1\n"
        "\n"
        "# A block over two lines:\n"
        "# - FIRST, SECOND: both of them,\n"
        "#   on two lines.\n"
        "FIRST=a\n"
        "SECOND=b\n"
        "THIRD=c\n"
        "\n"
        "BARE=\n"
    )
    got = {n: d for n, _, d in sr.parse_deploy_env(text)}
    assert got == {"ALONE": "The only one", "FIRST": "both of them, on two lines.",
                   "SECOND": "both of them, on two lines.", "THIRD": "", "BARE": ""}


def test_defaults_never_show_a_password():
    assert sr.show_default("X_URL", "postgresql://u:pw@h:5432/db", set()) == "`postgresql://u:…@h:5432/db`"
    assert sr.show_default("X_PASSWORD", "", {"X_PASSWORD"}) == sr.GENERATED
    assert sr.show_default("X_API_KEY", "", set()) == sr.WHEN_USED
